<?php\n\nnamespace App\Models;\n\nuse Illuminate\Database\Eloquent\Relations\Pivot;\nuse Illuminate\Database\Eloquent\Factories\HasFactory; // Keep if you plan to have factories for it\n\nclass RolePermission extends Pivot\n{\n    use HasFactory;\n\n    public $incrementing = false;\n    public $timestamps = false;\n    protected $table = 'role_permissions'; // Explicitly define table name for clarity\n    protected $primaryKey = ['role_id', 'permission_id'];\n\n    protected $fillable = [\n        'role_id',\n        'permission_id',\n    ];\n\n    public function role()\n    {\n        return $this->belongsTo(Role::class);\n    }\n\n    public function permission()\n    {\n        return $this->belongsTo(Permission::class);\n    }\n}
